#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    int n = static_cast<int>(s.size());
    if (n < 3 || n > 21) {
        cout << -1 << '\n';
        return 0;
    }

    int ans = -1;

    for (int i = 0; i < n - 2; ++i) {
        for (int j = i + 1; j < n - 1; ++j) {
            int lengths[] = {i + 1, j - i, n - j - 1};
            int starts[] = {0, i + 1, j + 1};
            int values[3] = {};
            bool valid = true;

            for (int k = 0; k < 3; ++k) {
                if (lengths[k] > 7 ||
                    (lengths[k] > 1 && s[starts[k]] == '0')) {
                    valid = false;
                    break;
                }

                for (int p = starts[k]; p < starts[k] + lengths[k]; ++p) {
                    values[k] = values[k] * 10 + (s[p] - '0');
                }

                if (values[k] > 1000000) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                ans = max(ans, values[0] + values[1] + values[2]);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

