            int y = stoi(s.substr(i, j - i));
            int z = stoi(s.substr(j));

            if (x <= 1000000 && y <= 1000000 && z <= 1000000) {
                ans = max(ans, x + y + z);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

